import fs from "node:fs/promises";
import path from "node:path";
import { finishesFromText, type Finish } from "../appearance";
import { MATERIALS } from "../materials";
import { hexColor, norm, tokens } from "../enrich/text";

// Reads OrcaSlicer user filament presets (user/default/filament/*.json).
// These are treated as untrusted starting points: many were generated by
// spoolman2slicer with template values (flow 0.94, a Voron base) or are
// half-edited copies. The import only proposes an identity for each file
// and keeps the slicer keys it set; the user confirms every row.

/** OrcaSlicer stores most values as single-element string arrays; "nil" means unset. */
export function orcaValue(v: unknown): string | null {
  const first = Array.isArray(v) ? v[0] : v;
  if (first === undefined || first === null) return null;
  const s = String(first).trim();
  return s === "" || s === "nil" ? null : s;
}

const orcaNumber = (v: unknown): number | null => {
  const s = orcaValue(v);
  const n = s == null ? NaN : Number(s);
  return Number.isFinite(n) ? n : null;
};

/** Keys worth keeping as calibration starting values (the ones Phase 2/3 tune). */
export const TUNABLE_KEYS = [
  "nozzle_temperature",
  "nozzle_temperature_initial_layer",
  "nozzle_temperature_range_low",
  "nozzle_temperature_range_high",
  "hot_plate_temp",
  "hot_plate_temp_initial_layer",
  "textured_plate_temp",
  "textured_plate_temp_initial_layer",
  "cool_plate_temp",
  "filament_flow_ratio",
  "enable_pressure_advance",
  "pressure_advance",
  "filament_max_volumetric_speed",
  "filament_retraction_length",
  "filament_retraction_speed",
  "filament_z_hop",
  "filament_z_hop_types",
  "filament_wipe",
  "filament_wipe_distance",
  "fan_min_speed",
  "fan_max_speed",
  "full_fan_speed_layer",
  "fan_cooling_layer_time",
  "slow_down_layer_time",
  "close_fan_the_first_x_layers",
] as const;

export interface OrcaImportRow {
  fileName: string;
  profileName: string;
  inherits: string | null;
  generatedBy: string | null;
  /** Proposed identity - editable in the preview before anything is saved. */
  vendor: string;
  material: string;
  line: string | null;
  colorName: string | null;
  colorHex: string | null;
  /** Read from words like "Silk" or "Transparent" in the name - inferred, not stated by the profile. */
  finishes: Finish[];
  density: number | null;
  diameterMm: number | null;
  spoolWeightG: number | null;
  costPerKg: number | null;
  nozzleMin: number | null;
  nozzleMax: number | null;
  /** The tunable slicer keys this file actually set. */
  settings: Record<string, string>;
  warnings: string[];
}

const MATERIAL_TYPES = [...MATERIALS.map((m) => m.type)].sort((a, b) => b.length - a.length); // PLA-CF before PLA

function materialFrom(...texts: (string | null | undefined)[]): string | null {
  for (const t of texts) {
    if (!t) continue;
    const upper = t.toUpperCase();
    const hit = MATERIAL_TYPES.find((m) => new RegExp(`(^|[^A-Z])${m.replace("-", "\\-")}([^A-Z]|$)`).test(upper));
    if (hit) return hit;
  }
  return null;
}

// Words that describe the profile, not the filament: "@System", "Copy", "1.75mm", ".4 nozzle".
const NOISE = /^(@?system|copy|nozzle|generic|\.?\d+(\.\d+)?(mm)?|\d+g|\d+kg)$/i;

/** Remove the vendor and material words from a profile name, leaving line/color. */
function remainder(name: string, vendor: string, material: string): string {
  const vendorTokens = new Set(tokens(vendor));
  return name
    .split(/[\s]+/)
    .filter((w) => w !== "-" && w !== "")
    .filter((w) => !vendorTokens.has(w.toLowerCase().replace(/[^a-z0-9+]/g, "")))
    .filter((w) => norm(w) !== norm(material))
    .filter((w) => !NOISE.test(w))
    .join(" ")
    .replace(/^[-\s]+|[-\s]+$/g, "")
    .trim();
}

export function parseOrcaFilament(fileName: string, json: Record<string, unknown>): OrcaImportRow {
  const warnings: string[] = [];
  const profileName = String(json.name ?? path.basename(fileName, ".json"));
  const inherits = typeof json.inherits === "string" && json.inherits ? json.inherits : null;
  const generatedBy = /spoolman2slicer/i.test(String(json._comment ?? "")) ? "spoolman2slicer" : null;

  // "Vendor - Name" is spoolman2slicer's filename pattern.
  // A part before the dash that names a material ("SUNLU PETG @System - Copy")
  // is a copied preset, not that pattern.
  const baseName = path.basename(fileName, ".json");
  const dashed = baseName.includes(" - ") && !materialFrom(baseName.split(" - ")[0]) ? baseName.split(" - ") : null;

  const fileType = orcaValue(json.filament_type);
  const material = (fileType ?? materialFrom(profileName, baseName, inherits) ?? "PLA").toUpperCase();
  if (!fileType && !materialFrom(profileName, baseName, inherits)) warnings.push("Material couldn't be determined; assumed PLA.");
  if (fileType && inherits && materialFrom(inherits) && materialFrom(inherits) !== fileType.toUpperCase())
    warnings.push(`Inherits “${inherits}”, which is a different material than its filament type ${fileType}.`);

  let vendor = orcaValue(json.filament_vendor);
  if (!vendor || /^generic$/i.test(vendor)) vendor = dashed?.[0] ?? null;
  if (!vendor) {
    const first = profileName.split(/\s+/)[0];
    if (first && !materialFrom(first) && !/^(generic|creality)$/i.test(first)) vendor = first;
  }
  if (!vendor) {
    vendor = "Unknown";
    warnings.push("No vendor in the profile; set one before importing.");
  }
  // "SUNLU", "DeepLee" -> the casing other profiles of the same brand use is applied at import.

  const rest = remainder(dashed ? dashed.slice(1).join(" ") : profileName, vendor, material);
  // A material-ish word left in the remainder ("Silk PLA Silver" -> "Silk Silver") hints at the line.
  const lineWord = rest.match(/\b(silk|matte|wood|marble|glitter|sparkle|glow|translucent|transparent|carbon|high speed)\b/i)?.[0] ?? null;
  // ...and comes off the color when it opens or closes it ("Walnut Wood" -> "Walnut",
  // "Silk Silver" -> "Silver"), unless that leaves a fragment ("Glow in The Dark Blue").
  let colorName = rest || null;
  if (colorName && lineWord) {
    const stripped = colorName.replace(new RegExp(`^${lineWord}\\s+|\\s+${lineWord}$`, "i"), "").trim();
    if (stripped && stripped !== colorName && !/^(in|of|the|and)\b/i.test(stripped)) colorName = stripped;
  }

  if (generatedBy && orcaValue(json.filament_flow_ratio) === "0.94")
    warnings.push("Flow ratio 0.94 is spoolman2slicer's template default, not a calibrated value.");
  if (inherits && /^voron/i.test(inherits)) warnings.push(`Inherits “${inherits}”, a Voron base that doesn't match an Ender-3 V2.`);

  const settings: Record<string, string> = {};
  for (const key of TUNABLE_KEYS) {
    const v = orcaValue(json[key]);
    if (v != null) settings[key] = v;
  }

  return {
    fileName,
    profileName,
    inherits,
    generatedBy,
    vendor,
    material,
    line: lineWord ? lineWord[0].toUpperCase() + lineWord.slice(1).toLowerCase() : null,
    colorName,
    colorHex: hexColor(orcaValue(json.default_filament_colour)),
    finishes: finishesFromText(`${lineWord ?? ""} ${profileName} ${baseName}`),
    density: orcaNumber(json.filament_density),
    diameterMm: orcaNumber(json.filament_diameter),
    spoolWeightG: orcaNumber(json.filament_spool_weight),
    costPerKg: orcaNumber(json.filament_cost),
    nozzleMin: orcaNumber(json.nozzle_temperature_range_low),
    nozzleMax: orcaNumber(json.nozzle_temperature_range_high),
    settings,
    warnings,
  };
}

/** Every user filament preset in the folder (not base/ or other subfolders). */
export async function readUserFilamentProfiles(userDir: string): Promise<OrcaImportRow[]> {
  const dir = path.join(userDir, "filament");
  const files = (await fs.readdir(dir)).filter((f) => f.endsWith(".json")).sort((a, b) => a.localeCompare(b));
  const rows: OrcaImportRow[] = [];
  for (const f of files) {
    try {
      rows.push(parseOrcaFilament(f, JSON.parse(await fs.readFile(path.join(dir, f), "utf8"))));
    } catch {
      // A malformed file shouldn't block importing the rest.
    }
  }
  return rows;
}
